solutionCode:
fun doubleScores(scores: List<Int>): List<Int> {
    return scores.map { it * 2 }
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testDoubleScores() {
        Assert.assertEquals(listOf(90, 144, 76), doubleScores(listOf(45, 72, 38)))
    }

    @Test
    fun testDoubleEmpty() {
        Assert.assertEquals(emptyList<Int>(), doubleScores(emptyList()))
    }

    @Test
    fun testDoubleSingle() {
        Assert.assertEquals(listOf(200), doubleScores(listOf(100)))
    }

    @Test
    fun testDoubleWithZero() {
        Assert.assertEquals(listOf(0, 20, 40), doubleScores(listOf(0, 10, 20)))
    }
}
